<script setup lang="ts">
import { computed, watch, ref } from 'vue'
import { useRoute } from 'vue-router'
import { discoverApi, licenseLabel } from '@/api/discover'
import CommunityBack from '@/components/community/CommunityBack.vue'
import RequestState from '@/components/community/RequestState.vue'
import { useCommunityResource } from '@/components/community/resource'
import { displayDate, webLink } from '@/components/community/contract'
import { useHead } from '@/lib/head'
import '@/components/community/community.css'
const route = useRoute()
const key = computed(() => String(route.params.key || ''))
const { data, loading, error, load } = useCommunityResource(() => discoverApi.tool(key.value))
const copyStatus = ref('')
watch(key, () => { copyStatus.value = ''; void load() }, { immediate:true })
async function copyHash(hash:string) {
  try { await navigator.clipboard.writeText(hash); copyStatus.value = 'SHA-256 已复制' }
  catch { copyStatus.value = '复制失败，请长按或选中下方校验值复制' }
}
function bytes(value:number) { return value >= 1048576 ? `${(value/1048576).toFixed(1)} MB` : `${(value/1024).toFixed(1)} KB` }
function platform(raw:string) { return ({windows:'Windows',macos:'macOS',linux:'Linux',android:'Android',ios:'iOS'} as Record<string,string>)[raw] || raw }
function arch(raw?:string) { return ({aarch64:'ARM64',x86_64:'x64',x86:'x86',universal:'通用',armv7:'ARMv7'} as Record<string,string>)[raw || ''] || '架构待确认' }
useHead(() => ({ title:data.value?.name || '工具详情' }))
</script>
<template><main class="community-page"><CommunityBack fallback="/resources" label="AI 工具" /><RequestState :loading="loading" :error="error" @retry="load" /><template v-if="data"><article class="community-detail tool-intro"><div class="tool-title"><img v-if="webLink(data.icon_url)" :src="webLink(data.icon_url)" alt="" @error="($event.target as HTMLImageElement).style.display = 'none'"><div><span v-if="data.sample" class="community-sample">示例数据</span><h1>{{ data.name }}</h1><p v-if="data.developer || data.type_label" class="community-meta">{{ [data.developer, data.type_label].filter(Boolean).join(' · ' ) }}</p><p class="community-meta">{{ licenseLabel(data.license) }}<span v-if="data.license_spdx"> · {{ data.license_spdx }}</span><span v-if="data.latest_version"> · {{ data.latest_version }}</span><span v-if="data.latest_date"> · {{ displayDate(data.latest_date) }}</span></p></div></div><p v-if="data.description" class="description">{{ data.description }}</p><p v-if="data.platforms?.length" class="community-meta">{{ data.platforms.map(platform).join(' · ') }}</p><div class="links"><a v-if="webLink(data.homepage_url)" :href="webLink(data.homepage_url)" class="community-button" target="_blank" rel="noopener noreferrer">官方网站 ↗</a><a v-if="webLink(data.release_url)" :href="webLink(data.release_url)" class="community-button" target="_blank" rel="noopener noreferrer">官方发布页 ↗</a><a v-if="webLink(data.license_source_url)" :href="webLink(data.license_source_url)" class="community-button" target="_blank" rel="noopener noreferrer">许可证 ↗</a></div><p v-if="data.source || data.as_of" class="community-meta">{{ data.source }}<span v-if="data.as_of"> · 采集于 {{ displayDate(data.as_of) }}</span></p><details v-if="data.collection_notes?.length" class="notes"><summary>采集说明</summary><p v-for="(note,index) in data.collection_notes" :key="index">{{ note }}</p></details></article>
<section v-if="data.artifacts?.length" class="community-detail community-block"><h2>下载产物</h2><p class="community-meta">按系统与架构选择。下载后可用 SHA-256 核对文件。</p><p v-if="copyStatus" class="community-meta" role="status">{{ copyStatus }}</p><article v-for="(artifact,index) in data.artifacts" :key="artifact.asset_id || index" class="artifact"><h3>{{ platform(artifact.os) }} · {{ arch(artifact.arch) }}</h3><p class="filename">{{ artifact.filename || artifact.desc }}<span v-if="artifact.size"> · {{ bytes(artifact.size) }}</span></p><div class="links"><a v-if="webLink(artifact.github_url)" :href="webLink(artifact.github_url)" class="community-button" target="_blank" rel="noopener noreferrer">官方来源 ↗</a><a v-if="webLink(artifact.mirror_url)" :href="webLink(artifact.mirror_url)" class="community-button" target="_blank" rel="noopener noreferrer">小伴镜像 ↗</a><button v-if="artifact.sha256" class="community-button" @click="copyHash(artifact.sha256)">复制校验值</button></div><details v-if="artifact.sha256"><summary>SHA-256<span v-if="artifact.hash_source"> · {{ artifact.hash_source }}</span></summary><code>{{ artifact.sha256 }}</code></details></article></section>
<section v-if="data.releases?.length" class="community-detail community-block"><h2>更新记录</h2><details v-for="release in data.releases" :key="release.version" class="release"><summary>{{ release.version }} <span class="community-meta">{{ displayDate(release.date) }}</span></summary><ul v-if="release.items?.length"><li v-for="(item,index) in release.items" :key="index">{{ item.text }}</li></ul><a v-if="webLink(release.url)" :href="webLink(release.url)" target="_blank" rel="noopener noreferrer" class="community-back">完整发布说明 ↗</a></details></section><div v-if="data.discussion_tag" class="community-detail community-block"><RouterLink :to="`/tag/${encodeURIComponent(data.discussion_tag)}`" class="community-button">社区讨论 · {{ data.discussion_count }}</RouterLink></div>
</template></main></template>
<style scoped>
h2 { margin:0 0 12px; font-size:16px; } .tool-title { display:flex; align-items:center; gap:16px; } .tool-title img { width:56px; height:56px; object-fit:contain; border-radius:8px; } .tool-title > div { min-width:0; } .community-page .tool-title h1 { margin:0; font-size:20px; line-height:1.4; } .tool-title .community-meta { margin:4px 0 0; } .community-page .tool-intro { border-radius:16px; } @media(max-width:767px) { .community-page .community-detail { margin-left:12px; margin-right:12px; border-radius:16px; } } .description { overflow-wrap:anywhere; white-space:pre-line; font-size:14px; } .links { display:flex; flex-wrap:wrap; gap:8px; margin-top:12px; } .artifact { padding:16px 0; border-top:.5px solid var(--line); } h3 { font-size:15px; margin:0 0 8px; } .filename { font-size:12px; color:var(--ink-3); overflow-wrap:anywhere; } details { margin-top:12px; font-size:12px; } summary { min-height:44px; align-content:center; cursor:pointer; color:var(--ink-2); } code { display:block; padding:12px; background:var(--surface-2); overflow-wrap:anywhere; white-space:normal; font-size:12px; border-radius:8px; } .notes p { font-size:12px; color:var(--ink-3); } .release { border-top:.5px solid var(--line); } .release li { line-height:1.8; font-size:14px; }
</style>
